import{ENVIRONMENT}from'./environment-registration.mjs';
import{animatePixels,lighting}from'./selected-environment-core.mjs';
import{GYM12}from'./registration.mjs';
const own=(o,k)=>Object.hasOwn(o,k),dirs=['up','down','left','right'];
const digest=async b=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',b)),v=>v.toString(16).padStart(2,'0')).join('');
export async function loadGym12Provider(no,{signal,presentation=true}={}){
 const r=GYM12[no];if(!r)throw Error('GYM12_NUMBER');let disposed=false,hasDraw=false,issuedFrame=null,issuedPixels=null;const masks=new Map,images=new Map;let water,leaves;const background=presentation?new OffscreenCanvas(...r.size):null,bg=background?.getContext('2d');
 async function bytes(file,hash){const res=await fetch(new URL(file,import.meta.url),{signal});if(!res.ok)throw Error('GYM12_RESOURCE_HTTP');const b=await res.arrayBuffer();if(await digest(b)!==hash)throw Error('GYM12_PIN_MISMATCH');return b}
 async function bitmap(pin){if(images.has(pin.file))return;const b=await bytes(pin.file,pin.sha256);const im=await createImageBitmap(new Blob([b],{type:'image/png'}));images.set(pin.file,im)}
 const dispose=()=>{if(disposed)return;disposed=true;for(const im of images.values())im.close();images.clear();masks.clear();issuedFrame=null;issuedPixels=null;hasDraw=false;signal?.removeEventListener('abort',dispose)};
 try{if(presentation)await bitmap(r.image);for(const [state,p]of Object.entries(r.states)){const rows=JSON.parse(new TextDecoder().decode(await bytes(p.maskFile,p.maskSHA))),mask=new Uint8Array(r.size[0]*r.size[1]);for(const[y,a,b]of rows)mask.fill(1,y*r.size[0]+a,y*r.size[0]+b);masks.set(+state,mask);if(presentation)for(const patch of p.patches)await bitmap(patch)}if(presentation){for(const f of r.foreground)await bitmap(f);water=new Uint32Array(await bytes(ENVIRONMENT[no].water.file,ENVIRONMENT[no].water.sha256));leaves=new Uint32Array(await bytes(ENVIRONMENT[no].leaves.file,ENVIRONMENT[no].leaves.sha256));}if(signal?.aborted)throw Error('GYM12_ABORTED');signal?.addEventListener('abort',dispose,{once:true})}catch(e){dispose();throw e}
 const safe=(foot,state)=>!disposed&&masks.has(state)&&Array.isArray(foot)&&Object.getPrototypeOf(foot)===Array.prototype&&Reflect.ownKeys(foot).length===3&&foot.length===2&&['0','1'].every(k=>{const d=Object.getOwnPropertyDescriptor(foot,k);return d?.enumerable&&Object.hasOwn(d,'value')&&Number.isSafeInteger(d.value)})&&foot[0]>=0&&foot[1]>=0&&foot[0]<r.size[0]&&foot[1]<r.size[1]&&masks.get(state)[foot[1]*r.size[0]+foot[0]]===1;
 const describe=(foot,facing,state)=>{if(!safe(foot,state)||!dirs.includes(facing))throw Error('GYM12_POSE_SUPPORT');return {version:1,sceneId:r.sceneId,mapId:r.mapId,revision:r.revision,imageSHA:r.image.sha256,maskSHA:r.states[state].maskSHA,foot:[...foot],facing,state}};
 const validate=p=>{try{const keys=['version','sceneId','mapId','revision','imageSHA','maskSHA','foot','facing','state'];if(!p||Object.getPrototypeOf(p)!==Object.prototype||Reflect.ownKeys(p).length!==keys.length)return false;const values={};for(const k of keys){const d=Object.getOwnPropertyDescriptor(p,k);if(!d?.enumerable||!own(d,'value'))return false;values[k]=d.value}return Object.entries(describe(values.foot,values.facing,values.state)).every(([k,v])=>JSON.stringify(v)===JSON.stringify(values[k]))}catch{return false}};
 const draw=(ctx,camera,state,{timeMs=0,nightMix=0,waterOn=true,leafOn=true}={})=>{issuedFrame=null;issuedPixels=null;hasDraw=false;if(disposed||!presentation||!r.states[state])return false;if(!Number.isFinite(timeMs)||!Number.isFinite(nightMix)||nightMix<0||nightMix>1)throw Error('GYM12_ENVIRONMENT_CLOCK');bg.clearRect(0,0,...r.size);bg.drawImage(images.get(r.image.file),0,0);for(const p of r.states[state].patches)bg.drawImage(images.get(p.file),...p.xy);const source=bg.getImageData(0,0,...r.size);const{pixels}=animatePixels(source.data,water,leaves,...r.size,timeMs,{waterOn,leafOn});bg.putImageData(new ImageData(pixels,...r.size),0,0);lighting(bg,ENVIRONMENT[no].row,nightMix);ctx.drawImage(background,-(camera?.x??0),-(camera?.y??0));hasDraw=true;return true};
 const currentFrame=()=>{if(disposed||!presentation||!hasDraw)throw Error('GYM12_PRESENTATION_UNAVAILABLE');issuedFrame=bg.getImageData(0,0,...r.size);issuedPixels=new Uint8ClampedArray(issuedFrame.data);return issuedFrame};
 // Foreground contains masks, NOT display RGB. Restore current lit/state pixels only.
 const restoreForeground=(ctx,currentFrame,actorFoot)=>{if(disposed||!presentation)return false;if(currentFrame!==issuedFrame||!issuedPixels)throw Error('GYM12_CURRENT_FRAME_PROVENANCE');if(currentFrame.width!==r.size[0]||currentFrame.height!==r.size[1]||ctx.canvas.width!==r.size[0]||ctx.canvas.height!==r.size[1])throw Error('GYM12_FOREGROUND_NATIVE_FRAME');const maskCanvas=new OffscreenCanvas(...r.size),mq=maskCanvas.getContext('2d');for(const p of r.foreground)if(actorFoot[1]<=p.baseY)mq.drawImage(images.get(p.file),0,0);const mask=mq.getImageData(0,0,...r.size).data,out=ctx.getImageData(0,0,...r.size);for(let i=0;i<mask.length;i+=4)if(mask[i+3])out.data.set(issuedPixels.subarray(i,i+4),i);ctx.putImageData(out,0,0);return true};
 return Object.freeze({registration:r,pinsVerified:true,safe,describe,validate,draw,currentFrame,restoreForeground,dispose});
}

export const loadGym12Support=(no,options={})=>loadGym12Provider(no,{...options,presentation:false});
